//
// Они ничего нового не вводят, просто показывают,
// как эти линзы ожидается комбинировать.
// ───────────────────────────────────────────────────────────────────────────────

/** Типичный засадный хищник уровня IQ2 (условный «кот/змея без яда»). */
export const IQ2_AMBUSH_PREDATOR_PROFILE: MemeId[] = [
	...IQ2_BASE_MEMES,
	...IQ2_PREDATOR_LENS,
	...IQ2_AMBUSH_HUNTER_STYLE_LENS,
	...IQ2_BITE_HUNTER_STYLE_LENS,
