	...IQ2_BITE_HUNTER_STYLE_LENS,
];

/** Чистый падальщик. */
export const IQ2_SCAVENGER_PROFILE: MemeId[] = [
	...IQ2_BASE_MEMES,
	...IQ2_SCAVENGER_LENS,
