/** Травоядное, которое иногда не против мыши — будем строить уже от травоядного профиля. */
export const IQ2_HERBIVORE_WITH_OPPORTUNISM_PROFILE: MemeId[] = [
	// сюда позже добавим HERBIVORE-базу,
	// пока только показываю, как использовать линзу:
	...IQ2_BASE_MEMES,
	...IQ2_OPPORTUNISTIC_CARNIVORE_LENS,
