// ───────────────────────────────────────────────────────────────
// СЕНСОРНЫЕ ЛИНЗЫ (морфология органов чувств)
// ───────────────────────────────────────────────────────────────

export const IQ2_CHEMOSENSE_LENS: MemeId[] = [
    tech.sensing.chemosense_basic,
];

export const IQ2_VIBROSENSE_LENS: MemeId[] = [
    tech.sensing.vibration_basic,
