```ts
// world/world-hex.ts
// Базовая модель мира на гексагонах с объёмом ячейки и содержимым.

// ───────────────────────────────────────────────────────────────
// Координаты и идентификаторы гексов
// ───────────────────────────────────────────────────────────────

/**
 * Аксиальные координаты гекса (flat-top).
 * 1 гекс ≈ 1 м² пригодной для стояния площади.
 */
export interface HexCoord {
	q: number; // "колонка"
	r: number; // "строка"
}

/** Строковый ID гекса, чтобы удобно держать в словарях/картах. */
export type HexId = string;

export function hexId(coord: HexCoord): HexId {
	return `${coord.q};${coord.r}`;
}

/** Смещения соседей для flat-top axial (q, r). */
export const HEX_NEIGHBOR_OFFSETS: readonly HexCoord[] = [
	{ q: +1, r: 0 },
	{ q: +1, r: -1 },
	{ q: 0, r: -1 },
	{ q: -1, r: 0 },
	{ q: -1, r: +1 },
	{ q: 0, r: +1 },
];

export function addHex(a: HexCoord, b: HexCoord): HexCoord {
	return { q: a.q + b.q, r: a.r + b.r };
}

export function neighborsOf(coord: HexCoord): HexCoord[] {
	return HEX_NEIGHBOR_OFFSETS.map((o) => addHex(coord, o));
}

// ───────────────────────────────────────────────────────────────
// Объём / вместимость
// ───────────────────────────────────────────────────────────────

/**
 * Абстрактные "объёмные единицы".
 *
 * Предлагаемая шкала (можно калибровать под GURPS):
 *  - 1.0  — "один средний человек" в стойке;
 *  - 0.5  — маленькое существо / ребёнок / полусогнутый;
 *  - 1.5+ — крупный, в доспехах, с рюкзаком и т.п.;
 *  - 2–3  — очень крупный / толстый / с массивным снаряжением.
 *
 * По умолчанию гекс вмещает 3 единицы объёма:
 *  - 1 человек комфортно;
 *  - 2–3 — в тесноте / схватке.
 */
export type VolumeUnits = number;

/** Дефолтная вместимость гекса. */
export const DEFAULT_HEX_VOLUME_CAPACITY: VolumeUnits = 3;

// ───────────────────────────────────────────────────────────────
// Типы содержимого гекса
// ───────────────────────────────────────────────────────────────

export type HexContentKind = 'creature' | 'item' | 'structure';

/**
 * Базовая запись о том, что "что-то занимает место в гексе".
 * Это тонкий слой над реальными сущностями (актёрами, предметами, структурами).
 */
export interface HexContentInstance {
	id: string;              // уникальный ID этого размещения
	kind: HexContentKind;
	hexId: HexId;
	volume: VolumeUnits;     // сколько объёма съедает в этой ячейке

	// Ссылки наружу (ровно одна из них должна быть заполнена по kind)
	creatureId?: string;
	itemInstanceId?: string;
	structureId?: string;
}

/**
 * Ячейка карты. В ней нет "живых" данных предметов/существ,
 * только агрегированная вместимость и ссылки на содержимое.
 */
export interface HexCell {
	id: HexId;
	coord: HexCoord;

	/** Максимально допустимый суммарный volume содержимого. */
	volumeCapacity: VolumeUnits;

	/** ID всех HexContentInstance, которые сейчас в этом гексе. */
	contentIds: string[];
}

/**
 * Подсчёт уже занятого объёма в гексе.
 * Внешний код должен передать реальные объекты содержимого.
 */
export function usedVolume(cell: HexCell, contents: HexContentInstance[]): VolumeUnits {
	return contents.reduce((sum, c) => sum + c.volume, 0);
}

/**
 * Можно ли добавить ещё одно содержимое в гекс с учётом объёма.
 */
export function canFitIntoHex(
	cell: HexCell,
	contentsInCell: HexContentInstance[],
	newContent: HexContentInstance,
): boolean {
	const current = usedVolume(cell, contentsInCell);
	return current + newContent.volume <= cell.volumeCapacity;
}

// ───────────────────────────────────────────────────────────────
// Предметы и ресурс "еда"
// ───────────────────────────────────────────────────────────────

/**
 * Тип предмета-ресурса. Это именно "чертёж", а не конкретный объект.
 * Здесь задаём физические и ресурсные свойства.
 */
export interface ItemType {
	id: string;             // 'small_rodent_carcass', 'bird_egg', 'rusty_sword'
	name: string;
	baseVolume: VolumeUnits; // объём одной единицы
	isFood: boolean;
	foodEnergy?: number;    // условные "калории", если это еда
	foodQuality?: 'FRESH' | 'STALE' | 'ROTTEN';
	// позже можно добавить тэги, материалы и т.п.
}

/**
 * Конкретный инстанс предмета в мире.
 * Может лежать в гексе (через HexContentInstance) или быть в инвентаре существа.
 */
export interface ItemInstance {
	id: string;
	typeId: string;  // ссылка на ItemType
	stack: number;   // количество штук (для мелких предметов/еды)
}

/**
 * Удобная функция получить суммарный объём стопки предметов.
 */
export function itemStackVolume(type: ItemType, instance: ItemInstance): VolumeUnits {
	return type.baseVolume * instance.stack;
}

// ───────────────────────────────────────────────────────────────
// Актёр (существо) и метаболизм
// ───────────────────────────────────────────────────────────────

/**
 * Базовое описание физики существа, нужное для "места в гексе".
 * Всё остальное (мемы, потребности, IQ и т.п.) живёт в других слоях.
 */
export interface CreaturePhysicalProfile {
	/** Нормальный объём в стойке / рабочей позе. */
	baseVolume: VolumeUnits;

	/**
	 * Возможное "ужимание" (сидя, лежа, свернувшись).
	 * Например, змея может сильно уменьшить занимаемую площадь.
	 */
	minVolume: VolumeUnits;

	/** Максимальная вместимость переносимого инвентаря в объёмных единицах. */
	carryVolumeCapacity: VolumeUnits;
}

/**
 * Профиль метаболизма — сколько еды нужно этому существу.
 */
export interface MetabolismProfile {
	/** Сколько foodEnergy соответствует полной сытости (от 0 до 100%) */
	foodEnergyForFullSatiety: number;

	/** Базовый расход "калорий" за условный такт/ход. */
	basalFoodEnergyPerTurn: number;
}

/**
 * Состояние существа в мире, в привязке к гексам.
 * Здесь нет логики потребностей, только физика и позиция.
 */
export interface CreatureState {
	id: string;
	name: string;

	hexId: HexId;

	physical: CreaturePhysicalProfile;
	metabolism: MetabolismProfile;

	/** Текущая занятость гекса этим существом (может сжиматься/расширяться). */
	currentVolume: VolumeUnits;

	/** Список itemInstanceId в "инвентаре" существа. */
	inventoryItemIds: string[];
}

/**
 * Пример утилиты для оценки, сколько "сытости" даёт еда конкретному существу.
 * Здесь мы сознательно НЕ меняем потребности, только считаем долю.
 *
 * energyEaten       — сколько foodEnergy реально съели (сумма по ресурсам),
 * metabolism.foodEnergyForFullSatiety — "норма на сытость" для этого вида/особи.
 */
export function estimateFoodSatietyGain(
	metabolism: MetabolismProfile,
	energyEaten: number,
): number {
	if (metabolism.foodEnergyForFullSatiety <= 0) return 0;
	const share = energyEaten / metabolism.foodEnergyForFullSatiety;
	// ограничиваем в разумном диапазоне 0..1 (или чуть выше, если хочешь "объедание")
	return Math.max(0, Math.min(share, 1));
}

// ───────────────────────────────────────────────────────────────
// Срез состояния мира (минимальный каркас)
// ───────────────────────────────────────────────────────────────

export interface WorldState {
	hexes: Record<HexId, HexCell>;
	contents: Record<string, HexContentInstance>;
	itemTypes: Record<string, ItemType>;
	itemInstances: Record<string, ItemInstance>;
	creatures: Record<string, CreatureState>;
}
```

Это не лезет в твою текущую кодовую базу (memes, ActionDefinition и т.п.), а даёт чистый слой «мир на гексах + объём + еда как ресурс». Дальше поверх этого можно:

- привязать существующие `ActionDefinition` (действие смотрит в `WorldState`, решает, что можно сделать);
- навесить твои потребности/мемы, не трогая физику.

Про соседей и Godot — да, ты вспоминаешь **offset-координаты**, а я в примере использовал **axial**.

- В **axial (q,r)** соседи *не зависят* от чётности — один и тот же массив смещений работает для всех гексов.
- В Godot `TileMap` для hex по умолчанию как раз **offset** (odd-r / even-r или odd-q / even-q), поэтому там соседи действительно зависят от чётности строки/столбца.

Идея такая:  
**внутри симуляции** живём в axial (просто и красиво), а уже при обмене с Godot делаем конвертацию offset ↔ axial. Тогда твои проблемы с «разными смещениями» исчезают.

Плюс я посмотрел лист «Потребление»: там явное разделение на **Белковость / Энергия / Вес**. Ниже — обновлённый единый файл `world-hex.ts`, который:

- оставляет axial с константными смещениями соседей;
- даёт базовые конверторы offset ↔ axial (для flat-top, odd-q / even-q);
- расширяет `foodEnergy` до полноценного блока `nutrition` с **energy/protein/water**;
- вводит `NutritionNeeds` и утилиты, совместимые с твоей таблицей (6/60/3 для Human).

