	NutritionNeeds,
} from '../../from-gpt/world/actor.entity';
import { CreatureTemplateEntity } from '../creature/creature-template.entity';
import { CharacterEntity } from '../character/character.entity';

/**
 * Сервис, который знает как из доменных сущностей собрать ActorEntity
 * для симуляции (from-gpt/world).
 */
@Injectable()
export class ActorFactoryService {
	/**
	 * Создаёт актора для "звериного" CreatureTemplate.
	 */
	createFromTemplate(params: {
		template: CreatureTemplateEntity;
		hexId: HexId;
		id: string;
		name?: string;
	}): ActorEntity {
