		this.world = initialWorld;
	}

	getWorld(): WorldState {
		return this.world;
	}

	// Пример события: заспавнить актора
	spawnActor(payload: { actorId: string; hexId: HexId; /* ... */ }) {
		// здесь вызываем WorldState/ActorEntity методы
		// и apply(new ActorSpawnedEvent(...))
	}
}
```

Так:

- **версионируешь любую сцену** через события (как и хотел),
- можешь делать реплей сцен, «что было бы если» и т.п.,
- `from-gpt` остаётся библиотекой моделей и расчётных функций, а не сам становится агрегатом.

