	TERRITORY_MICROHABIT_EXPLORE,
} from '../../../from-gpt/etho/action-universal';
import {
	FLEE_TO_COVER,
	FREEZE_IN_PLACE,
	OBSERVATION,
	SHORT_DASH_ATTACK,
} from '../../../from-gpt/etho/action-small-vertebrate';

// ───────────────────────────────────────────────────────────────
// Базовый шаблон ящерицы (НЕ линза, а полноценная базовая сущность)
// ───────────────────────────────────────────────────────────────

export const LIZARD_TEMPLATE = new CreatureTemplateEntity({
	name: 'Small Lizard',
	sizeModifier: -6, // GURPS: SM-6 — крыса/мелкая ящерица
	primary: new PrimaryAttributesEntity({
		ST: 2,
		DX: 11,
		IQ: 2,
		HT: 10,
	} as any),
	// secondary — авто по primary

	// Базовые мемы: витал, уход, сенсорика, простое поведение
	memeIds: [
		IQ2,
		bio.vital.core,
		bio.vital.cold_blooded,

		core.perception,
		core.motor_coordination,

		eth.maintenance.cleanliness_core,
		eth.maintenance.thermoregulation,
		eth.maintenance.ecdysis,

		eth.sociality.solitary,

		// сенсорика как поведенческие "мемы"
		tech.sensing.vision_basic,
		tech.sensing.chemosense_basic,
		tech.sensing.vibration_basic,
	],

	// Базовая морфология: тело, размер, покровы, движение, сенсоры, оружие
	morphIds: [
		morph.body_plan.tetrapod_small_ground,
		morph.size.SMn6,
		morph.thermoreg.coldBlooded,
		morph.respiration.lungs_basic,
		morph.integument.scales_dry,

		morph.locomotion.crawl_quadruped,
		morph.locomotion.climb_rough_surface,

		morph.manip.mouth_only,
		morph.manip.forepaws_non_manip,

		morph.natural_weapon.bite_small,
		morph.natural_weapon.claws_small,

		morph.sense.vision_basic,
		morph.sense.vision_binocular,
		morph.sense.olfaction_basic,
		morph.sense.hearing_basic,
		morph.sense.vibration_ground,
	],

	// Базовые действия:
	//  - поесть/попить,
	//  - поспать,
	//  - погреться,
	//  - исследовать микробиотоп,
	//  - убежать/замереть/оглядеться.
	actionTags: [
		EAT_ACCEPTABLE.tag,
		EAT_POOR.tag,
		DRINK_DIRTY_WATER.tag,
		SLEEP_REST.tag,

		BASK_SUN_THERMOREGULATE.tag,
		TERRITORY_MICROHABIT_EXPLORE.tag,

		FLEE_TO_COVER.tag,
		FREEZE_IN_PLACE.tag,
		OBSERVATION.tag,
	],
});

// ───────────────────────────────────────────────────────────────
// Линза "засадный хищник"
// ───────────────────────────────────────────────────────────────

export const LIZARD_LENS_AMBUSH_PREDATOR: CreatureTemplateLens = {
	// Атрибуты можно не трогать, но если захочешь сделать "охотника позлее" —
	// сюда легко добавить primaryDelta: { DX: +1 } и т.п.

	memeIdsAdd: [
		eth.territory_marking,

		eth.predation.core,
		eth.predation.drive.prey_drive,
		eth.predation.drive.opportunistic,

		eth.tactics.ambush_stalk,

		tech.combat.core,
		tech.combat.bite_basic,
		tech.hunting.core,
	],

	// Морфы, если хотим выделить именно хищника (например, усилить оружие)
	// morphIdsAdd: [ ... ],

