## 2. Расширяем линзы и шаблон существа под нужды

### 2.1. `CreatureTemplateLens` + `CreatureTemplateEntity`

Дополняем интерфейс линзы и сущность шаблона:

```ts
// domain/creature/creature-template.entity.ts

import type { NeedTag } from '../../needs'; // поправишь путь под свой модуль

// ...

export interface CreatureTemplateLens {
	sizeModifierDelta?: number;

	primaryDelta?: Partial<{
		ST: number;
		DX: number;
		IQ: number;
		HT: number;
	}>;

	secondaryDelta?: Partial<{
		HP: number;
		FP: number;
		Will: number;
		Per: number;
		BasicSpeed: number;
		BasicMove: number;
	}>;

	memeIdsAdd?: MemeId[];
	morphIdsAdd?: MorphId[];
	actionTagsAdd?: string[];

	/** Нужды, которые добавляет линза (существо начинает их иметь). */
	needTagsAdd?: NeedTag[];
}

/**
 * Канонный шаблон существа.
 */
export class CreatureTemplateEntity extends NamedEntity {
	// ...

	public memeIds: MemeId[] = [];
	public morphIds: MorphId[] = [];
	public actionTags: string[] = [];

	/** Какие нужды вообще есть у существа (FOOD/WATER/REST/...). */
	public needTags: NeedTag[] = [];

	// ...

	applyLens(lens: CreatureTemplateLens): this {
		const {
			sizeModifierDelta,
			primaryDelta,
			secondaryDelta,
			memeIdsAdd,
			morphIdsAdd,
			actionTagsAdd,
			needTagsAdd,
		} = lens;

		if (typeof sizeModifierDelta === 'number' && !Number.isNaN(sizeModifierDelta)) {
			this.setSizeModifier(this.sizeModifier + sizeModifierDelta);
		}

		if (primaryDelta) {
			this.applyPrimaryDelta(primaryDelta);

			if (!secondaryDelta) {
				this.calculateSecondary();
			}
		}

		if (secondaryDelta) {
			this.applySecondaryDelta(secondaryDelta);
		}

		if (Array.isArray(memeIdsAdd) && memeIdsAdd.length > 0) {
			this.setMemeIds(
				Array.from(new Set([...this.memeIds, ...memeIdsAdd])),
			);
		}

		if (Array.isArray(morphIdsAdd) && morphIdsAdd.length > 0) {
			this.setMorphIds(
				Array.from(new Set([...this.morphIds, ...morphIdsAdd])),
			);
		}

		if (Array.isArray(actionTagsAdd) && actionTagsAdd.length > 0) {
			this.setActionTags(
				Array.from(new Set([...this.actionTags, ...actionTagsAdd])),
			);
		}

		if (Array.isArray(needTagsAdd) && needTagsAdd.length > 0) {
			this.setNeedTags(
				Array.from(new Set([...this.needTags, ...needTagsAdd])),
			);
		}

		return this;
	}

	// ...

	setNeedTags(needTags?: NeedTag[] | null): this {
		if (Array.isArray(needTags)) {
			this.needTags = [...needTags];
		} else {
			this.needTags = [];
		}
		return this;
	}
}
```

`applyPrimaryDelta/applySecondaryDelta/calculateSecondary` оставляем как в предыдущей версии — они уже ок.

