## 2. EAT / DRINK / SLEEP как «настоящие» экшены

Теперь обновим твой `world/actions/living-creature.actions.ts` так, чтобы он использовал `effects`.

```ts
// world/actions/living-creature.actions.ts

import { ActionDefinition, ActionEffect } from "./action-definition";
import { ActionTag } from "./action-tags";
import { NeedThresholdEnum } from "../needs/needs";
import type { NeedTag } from "../needs/needs";

/**
 * Потребности, с которыми работают базовые действия Living Creature.
 */
export const LIVING_CREATURE_NEEDS: Readonly<NeedTag[]> = [
	NeedTag.FOOD,
	NeedTag.WATER,
	NeedTag.REST,
];

/**
 * Общий эффект "поесть": съесть до maxMassLb фунтов еды из доступных источников
 * (инвентарь актора или гекс), передав это в систему метаболизма.
 */
const EAT_EFFECTS: ActionEffect[] = [
	{
		kind: 'consumeNutrition',
		source: 'actorOrHex',
		maxMassLb: 0.5, // по умолчанию за действие — до 0.5 фунта
	},
];

/**
 * Обобщённое действие "поесть".
 *
 * Важно:
 *  - это намерение найти и съесть еду, а не конкретное блюдо;
 *  - фактический эффект по FOOD/ENERGY/PROTEIN определяется тем,
 *    что именно нашлось и было съедено (NutritionContent ресурса).
 */
export const EAT: ActionDefinition = {
	tag: 'EAT' as ActionTag,

	needThresholds: {
		FOOD: {
			atLeast: NeedThresholdEnum.WARN,
		},
	},

	effects: EAT_EFFECTS,
};

/**
 * Общий эффект "попить": выпить до maxVolume воды из доступного источника.
 */
const DRINK_EFFECTS: ActionEffect[] = [
	{
		kind: 'consumeWater',
		source: 'actorOrHex',
		maxVolume: 0.5, // условная порция воды за одно действие
	},
];

/**
 * Обобщённое действие "попить".
 */
export const DRINK: ActionDefinition = {
	tag: 'DRINK' as ActionTag,

	needThresholds: {
		WATER: {
			atLeast: NeedThresholdEnum.WARN,
		},
	},

	effects: DRINK_EFFECTS,
};

/**
 * Общий эффект "поспать/отдохнуть".
 * Здесь мы не трогаем метаболизм напрямую — только REST.
 */
const SLEEP_EFFECTS: ActionEffect[] = [
	{
		kind: 'restoreRest',
		restPerTurn: 1.0,          // на такт/ход
		requiredPosture: 'lying',  // нужно лежать
	},
];

/**
 * Обобщённое действие "поспать / отдохнуть".
 */
export const SLEEP: ActionDefinition = {
	tag: 'SLEEP' as ActionTag,

	needThresholds: {
		REST: {
			atLeast: NeedThresholdEnum.IMPAIRED,
		},
	},

	effects: SLEEP_EFFECTS,
};

export const LivingCreatureActions: ActionDefinition[] = [
	EAT,
	DRINK,
	SLEEP,
];
```

