	/** Гейты по нуждам (как у тебя уже было). */
	needThresholds?: Partial<Record<NeedTag, NeedGate>>;

	/**
	 * Локальная логика экшена.
	 *
	 * Вся "магия" (движение ресурсов, метаболизм, изменение нужд)
	 * должна происходить здесь через методы ActionContext.
	 *
	 * Геймлуп просто выбирает экшен и зовёт perform(ctx).
	 */
	perform?(ctx: ActionContext): void;

	// остальные твои поля (rewardSecondary, tradeEffect, requiredMemes и т.п.)
	// остаются без изменений
