## 3. EAT / DRINK / SLEEP как полноценные экшены

Теперь перепишем твой `world/actions/living-creature.actions.ts`, чтобы он пользовался `perform`.

```ts
// world/actions/living-creature.actions.ts

import { ActionDefinition } from "./action-definition";
import { ActionTag } from "./action-tags";
import { NeedThresholdEnum, NeedTag } from "../needs/needs";
import type { ActionContext } from "./action-context";

/**
 * Потребности, с которыми работают базовые действия Living Creature.
 */
export const LIVING_CREATURE_NEEDS: Readonly<NeedTag[]> = [
	NeedTag.FOOD,
	NeedTag.WATER,
	NeedTag.REST,
];

/**
 * Обобщённое действие "поесть".
 *
 * Важно:
 *  - это намерение найти и съесть еду;
 *  - сколько и чего именно будет съедено — решает реализация ctx.consumeNutrition.
 */
export const EAT: ActionDefinition = {
	tag: 'EAT' as ActionTag,

	needThresholds: {
		FOOD: {
			atLeast: NeedThresholdEnum.WARN,
		},
	},

	perform(ctx: ActionContext): void {
		// За один "тик" пытаемся съесть до 0.5 фунта еды.
		// Конкретный источник (инвентарь актора / гекса) и
		// последствия по метаболизму — внутри ctx.consumeNutrition.
		ctx.consumeNutrition(0.5);
	},
};

/**
 * Обобщённое действие "попить".
 */
export const DRINK: ActionDefinition = {
	tag: 'DRINK' as ActionTag,

	needThresholds: {
		WATER: {
			atLeast: NeedThresholdEnum.WARN,
		},
	},

	perform(ctx: ActionContext): void {
		// Пытаемся выпить "порцию" воды (условный объём).
		ctx.consumeWater(0.5);
	},
};

/**
 * Обобщённое действие "поспать / отдохнуть".
 */
export const SLEEP: ActionDefinition = {
	tag: 'SLEEP' as ActionTag,

	needThresholds: {
		REST: {
			atLeast: NeedThresholdEnum.IMPAIRED,
		},
	},

	perform(ctx: ActionContext): void {
		// Восстанавливаем REST. Конкретная формула учтёт deltaTime/позу
		// и т.п. внутри реализации ctx.restoreRest.
		ctx.restoreRest(1.0);
	},
};

export const LivingCreatureActions: ActionDefinition[] = [
	EAT,
	DRINK,
		SLEEP,
];
```

Тут уже:

- **все важные вещи описаны непосредственно в экшене**:
  - на какие нужды он гейтится (`needThresholds`);
  - что он делает по факту (`perform` → вызывает нужный метод контекста с параметрами, которые тоже видны прямо здесь);
- геймлупу не нужно знать, что `EAT` → поедание ресурса; он просто вызывает `perform(ctx)`.

