		//   deltaTime: ctx.deltaTime,
		// });
	}
};

export const SLEEP: ActionDefinition = {
	tag: 'SLEEP' as ActionTag,

	needThresholds: {
		REST: {
			atLeast: NeedThresholdEnum.IMPAIRED,
		},
	},

	perform(ctx: ActionContext): void {
		// ctx.actor.restTick(ctx.deltaTime, ctx.hex);
	}
};

export const LivingCreatureActions: ActionDefinition[] = [
	EAT,
	DRINK,
	SLEEP,
];
```

Здесь уже всё честно по твоей модели мира:

- экшен **не просит мир что-то сделать**;
- он сам берёт `actor` и `hex` и **делает**: читает инвентарь, меняет свои поля, обновляет нужды.

Дальше ты можешь:

- добавить в `ActorEntity` методы типа `eatFromEnvironment`, `drinkFromEnvironment`, `restTick` — чтобы не размазывать одну и ту же логику по десятку экшенов;
- или наоборот, писать всю логику прямо в `perform`, если хочется максимальной локальности.

---

Если хочешь, следующим шагом можем детально расписать, **как именно** внутри `EAT.perform` искать еду по инвентарям актора/гекса, как накинуть туда `NutritionContent` и твой `MetabolismProfile`, не добавляя «магических» сервисов поверх — только методы на сущностях, как ты любишь.

