## 1. Поле профиля и сеттер/геттер

```ts
// actor.entity.ts

import { CreatureTemplateEntity } from "../../domain/character/creature-template.entity";
import { NeedTag } from "../needs/needs";
import type { ActionTag } from "../actions/action-tags";
import type { MemeId } from "../memes/memes";
import type { MorphId } from "../morphs/morphs";

// ...

export class ActorEntity {
	// ... уже существующие поля ...

	/**
	 * Профиль существа (по сути, "рассовый/видовой" шаблон из домена).
	 * Содержит:
	 *  - базовые primary/secondary;
	 *  - sizeModifier;
	 *  - набор мемов/морфов;
	 *  - список тегов действий;
	 *  - список тегов нужд (через линзы).
	 *
	 * Важно: Actor НЕ должен мутировать профиль — это "чертёж".
	 */
	protected creatureProfile: CreatureTemplateEntity | null = null;

	/**
	 * Текущие значения дефицитов по нуждам.
	 *  - 0 = дефицита нет;
	 *  - больше = хуже.
	 */
	protected needValues: Partial<Record<NeedTag, number>> = {};

	// ... конструктор ...

	constructor(params: {
		id: string;
		name?: string;
		// ...
		creatureProfile?: CreatureTemplateEntity | null;
	}) {
		// ... твои существующие setId/setName/и т.д. ...
		this
			// ...
			.setCreatureProfile(params.creatureProfile ?? null);
	}

	// ───────────────────────────────────────────────────────────
	// Профиль существа
	// ───────────────────────────────────────────────────────────

	/**
	 * Задать/сбросить профиль существа.
	 * Профиль воспринимаем как иммутабельный "чертёж".
	 *
	 * При назначении профиля можно:
	 *  - инициализировать нужды под его needTags;
	 *  - в будущем — инициализировать атрибуты, экшены и т.п.
	 */
	setCreatureProfile(profile?: CreatureTemplateEntity | null): this {
		this.creatureProfile = profile ?? null;

		// Автоинициализация нужд под профиль (если он их несёт).
		if (this.creatureProfile && Array.isArray(this.creatureProfile.needTags)) {
			for (const tag of this.creatureProfile.needTags as NeedTag[]) {
				// Не перезаписываем уже существующие значения, только инициализируем 0.
				if (this.needValues[tag] === undefined) {
					this.needValues[tag] = 0;
				}
			}
		}

		return this;
	}

	getCreatureProfile(): CreatureTemplateEntity | null {
		return this.creatureProfile;
	}

	/**
	 * Удобные геттеры для разных аспектов профиля.
	 * Возвращают readonly-массивы, чтобы профиль случайно не мутировали.
	 */

	getProfileActionTags(): readonly ActionTag[] {
		return (this.creatureProfile?.actionTags ?? []) as ActionTag[];
	}

	getProfileNeedTags(): readonly NeedTag[] {
		return (this.creatureProfile?.needTags ?? []) as NeedTag[];
	}

	getProfileMemeIds(): readonly MemeId[] {
		return (this.creatureProfile?.memeIds ?? []) as MemeId[];
	}

	getProfileMorphIds(): readonly MorphId[] {
		return (this.creatureProfile?.morphIds ?? []) as MorphId[];
	}

	/**
	 * Проверки "умеет ли этот актор вообще такое".
	 */

	hasActionTag(tag: ActionTag): boolean {
		const tags = this.getProfileActionTags();
		return tags.includes(tag);
	}

	hasNeedTag(tag: NeedTag): boolean {
		const tags = this.getProfileNeedTags();
		return tags.includes(tag);
	}

	hasMeme(memeId: MemeId): boolean {
		const ids = this.getProfileMemeIds();
		return ids.includes(memeId);
	}

	hasMorph(morphId: MorphId): boolean {
		const ids = this.getProfileMorphIds();
		return ids.includes(morphId);
	}

	// ───────────────────────────────────────────────────────────
	// Работа с нуждами (на которые будут опираться экшены)
	// ───────────────────────────────────────────────────────────

	/**
	 * Получить "сырой" дефицит по нужде (0..∞; 0 = дефицита нет).
	 */
	getNeedValue(tag: NeedTag): number {
		const raw = this.needValues[tag];
		return typeof raw === 'number' ? raw : 0;
	}

	/**
	 * Жёстко установить дефицит по нужде.
	 */
	setNeedValue(tag: NeedTag, value: number): this {
		const v = Number.isFinite(value) ? value : 0;
		this.needValues[tag] = Math.max(0, v);
		return this;
	}

	/**
	 * Прибавить дельту к дефициту (может быть отрицательной).
	 * Положительная дельта → хуже, отрицательная → лучше.
	 */
	changeNeedValue(tag: NeedTag, delta: number): this {
		if (!Number.isFinite(delta) || delta === 0) return this;
		const current = this.getNeedValue(tag);
		return this.setNeedValue(tag, current + delta);
	}

	/**
	 * Массовое изменение дефицитов по нескольким нуждам.
	 */
	applyNeedDeltas(deltas: Partial<Record<NeedTag, number>>): this {
		for (const [key, delta] of Object.entries(deltas)) {
			const tag = key as NeedTag;
			if (typeof delta === 'number' && delta !== 0) {
				this.changeNeedValue(tag, delta);
			}
		}
		return this;
	}

	// ... остальной код ActorEntity (advanceTime, стейты экшенов и т.д.) ...
}
```

---

## Как это теперь использовать в SLEEP / экшенах

Теперь у твоего `SLEEP` есть всё, что нужно:

- профиль можно получить как `ctx.actor.getCreatureProfile()`;
- список нужд, с которыми вообще имеет смысл работать — `getProfileNeedTags()`;
- REST менять через `changeNeedValue(NeedTag.REST, delta)`.

Пример адаптированного кусочка `perform` (идея, ты уже свой код накидал):

```ts
perform(deltaTime): void {
	const actor = this.ctx.actor;

	// Базовая длительность сна (8 часов) читается из морфов/профиля —
	// пока можно зашить константу, а потом вынести в SleepProfile,
	// привязанный к CreatureTemplateEntity.
	const sleepLengthMs = 8 * 60 * 60 * 1000; // 8h

	// "глубина" сна по зонной шкале (сколько зон мы хотим покрыть):
	const sleepZone =
		zoneRank(this.enterThresholds[NeedTag.REST].atLeast) -
		zoneRank(this.exitThresholds[NeedTag.REST].atMost);

	const reduceREST = sleepZone / sleepLengthMs * deltaTime;

	// дефицит уменьшается → дельта отрицательная:
	actor.changeNeedValue(NeedTag.REST, -reduceREST);
}
```

Когда доберёмся до морфов/профиля сна:

- добавим в `CreatureTemplateEntity` что-то вроде `sleepProfile` (fullRestHours, restPerHour и т.п.);
- внутри SLEEP будем читать именно оттуда вместо константы `8h`;
- а морфы линзами будут модифицировать этот профайл (меньше нуждается в сне, быстрее восстанавливается и т.д.).

---

### Что даёт наличие профиля в акторе

- Любой экшен может:
  - проверить `actor.hasActionTag(this.tag)` прежде чем что-то делать;
  - понять, есть ли у существа вообще REST/FOOD/WATER (`hasNeedTag`);
  - при необходимости смотреть морфы (`hasMorph`) и мемы (`hasMeme`) для более сложной логики.

- Сам актор:
  - инициализирует только те нужды, которые реально заданы профилем;
  - не хранит ничего лишнего для големов/нежити (у которых профиль без `core.vital.living` и без `NeedTag.REST/FOOD/WATER`).

Если захочешь, следующим шагом можем:

- добавить в `CreatureTemplateEntity` `sleepProfile` в стиле GURPS (8 часов базовых → модификаторы морфов);
- и привязать к нему твой SLEEP-экшен так, чтобы длительность и скорость восстановления REST настраивались чисто через профиль/морфы, без магии в теле экшена.

Сделаем это аккуратно и по-твоему кодстайлу: отдельная сущность для профиля сна + поле и сеттер в `CreatureTemplateEntity`. Базовый профиль — 8 часов по-гурпсовски, а всё остальное можно уже править морфами/линзами.

