## 1. Новый файл: `domain/character/sleep-profile.entity.ts`

Цель: маленькая сущность, которую можно вешать на любой `CreatureTemplateEntity`.  
По умолчанию — **8 часов** сна для полной перезарядки, как в GURPS.

```ts
// domain/character/sleep-profile.entity.ts

/**
 * Профиль сна существа в "гурпсовом" духе.
 *
 * Сюда можно опираться:
 *  - при расчёте длительности сна (сколько часов нужно, чтобы выспаться);
 *  - при расчёте скорости восстановления REST во время сна.
 *
 * По умолчанию:
 *  - baseHours = 8       — "нормальный" взрослый человек;
 *  - minChunkHours = 0.5 — бессмысленно спать менее 30 минут;
 *  - maxChunkHours = 12  — один непрерывный эпизод сна вряд ли дольше;
 *  - restPerHour = 1 / baseHours — если REST нормирован на [0..1],
 *    то за baseHours часов сна можно полностью восстановиться.
 */
export class SleepProfileEntity {
	/** Сколько часов непрерывного сна нужно для полной перезарядки REST. */
	baseHours: number;

	/** Минимальный "осмысленный" кусок сна, часов. */
	minChunkHours: number;

	/** Максимальная длительность одного эпизода сна, часов. */
	maxChunkHours: number;

	/**
	 * Базовая скорость восстановления REST за час нормального сна.
	 * Если REST-дефицит нормирован на [0..1], то по умолчанию:
	 *   restPerHour = 1 / baseHours  -> за baseHours часов REST идёт из 1 в 0.
	 */
	restPerHour: number;

	constructor(params?: Partial<SleepProfileEntity>) {
		// Важно: порядок сеттеров — сначала baseHours, потом зависящее от него.
		this
			.setBaseHours(params?.baseHours)
			.setMinChunkHours(params?.minChunkHours)
			.setMaxChunkHours(params?.maxChunkHours)
			.setRestPerHour(params?.restPerHour);
	}

	setBaseHours(hours?: number): this {
		const h = typeof hours === 'number' && hours > 0 ? hours : 8; // GURPS-база
		this.baseHours = h;
		return this;
	}

	setMinChunkHours(hours?: number): this {
		const minDefault = 0.5; // 30 минут
		let h = typeof hours === 'number' && hours > 0 ? hours : minDefault;

		// не даём minChunkHours быть больше baseHours
		if (this.baseHours && h > this.baseHours) {
			h = this.baseHours;
		}
		this.minChunkHours = h;
		return this;
	}

	setMaxChunkHours(hours?: number): this {
		const maxDefault = this.baseHours ? this.baseHours : 8;
		let h = typeof hours === 'number' && hours > 0 ? hours : maxDefault;

		// maxChunkHours не должен быть меньше minChunkHours
		if (this.minChunkHours && h < this.minChunkHours) {
			h = this.minChunkHours;
		}
		this.maxChunkHours = h;
		return this;
	}

	setRestPerHour(restPerHour?: number): this {
		if (typeof restPerHour === 'number' && restPerHour > 0) {
			this.restPerHour = restPerHour;
			return this;
		}

		// Если ничего не задано — "полный REST за baseHours часов".
		const h = this.baseHours || 8;
		this.restPerHour = 1 / h;
		return this;
	}
}
```

