    tag: 'SLEEP' as ActionTag,
    ctx: undefined,

    enterThresholds: {
        [NeedTag.REST]: {
            atLeast: NeedThresholdEnum.IMPAIRED,
        },
    },

    exitThresholds: {
        [NeedTag.REST]: {
            atMost: NeedThresholdEnum.OK,
        },
    },

    onEnter(ctx: ActionContext) {
        this.ctx = ctx;
        const actor = ctx.actor;
        if (actor.isBusy()) return;
        actor.setAction(this)
    },

    perform(deltaTime): void {
        const actor = this.ctx.actor;

        const sleepLength = 8 * 60 * 60 * 1000; // 8h @TODO: make dynamic

        const sleepZone
            = zoneRank(this.enterThresholds[NeedTag.REST].atLeast)
            - zoneRank(this.exitThresholds[NeedTag.REST].atMost)

        const reduceREST = sleepZone / sleepLength * deltaTime;

        // @TODO: make method for altering actor needs!
    },
};
```

Меняем только расчёт `sleepLength` на морф-зависимый:

```ts
import { getDailySleepHoursForActor } from "../sleep/sleep-helpers";
import { NeedTag, NeedThresholdEnum } from "../needs/needs";
// ... остальные импорты ...

export const SLEEP: ActionDefinition = {
	tag: 'SLEEP' as ActionTag,
	ctx: undefined as unknown as ActionContext,

	enterThresholds: {
		[NeedTag.REST]: {
			atLeast: NeedThresholdEnum.IMPAIRED,
		},
	},

	exitThresholds: {
		[NeedTag.REST]: {
			atMost: NeedThresholdEnum.OK,
		},
	},

	onEnter(ctx: ActionContext) {
		this.ctx = ctx;
		const actor = ctx.actor;
		if (actor.isBusy()) return;
		actor.setAction(this);
	},

	perform(deltaTime: number): void {
		const actor = this.ctx.actor;

		// 1) Сколько часов сна этому существу нужно "в идеале"
		const dailySleepHours = getDailySleepHoursForActor(actor);

		// 2) Переводим в миллисекунды (у тебя уже ms в примере)
		const sleepLengthMs = dailySleepHours * 60 * 60 * 1000;

		// 3) "глубина" сна по зонной шкале (как у тебя было)
		const sleepZone =
			zoneRank(this.enterThresholds[NeedTag.REST].atLeast) -
			zoneRank(this.exitThresholds[NeedTag.REST].atMost);

		// 4) На сколько за этот тик уменьшаем дефицит REST:
		const reduceREST = (sleepZone / sleepLengthMs) * deltaTime;

		// дефицит REST уменьшается → дельта отрицательная
		actor.changeNeedValue(NeedTag.REST, -reduceREST);
	},
};
```

> Здесь всё ещё остаётся твой расчёт через `sleepZone` — я его не трогаю.  
> Главное изменение — **`sleepLength` теперь берётся из морфов (Less Sleep)**, а не жёстко `8h`.

