## 2. Хелперы для уровневых морфов

Отдельный файл, чтобы не засорять `morphs.ts`, например:  
`rps/morphs-leveled.ts`

```ts
// rps/morphs-leveled.ts

import type { LeveledMorphTemplateId, MorphId } from "./morphs";

/**
 * Сгенерировать конкретный MorphId из шаблона и уровня.
 *
 *   leveledMorph(morph.rest.lessSleep, 3)
 *   → "morph.rest.less-sleep.3"
 */
export function leveledMorph(
	template: LeveledMorphTemplateId,
	level: number,
): MorphId {
	const safeLevel = Number.isFinite(level) && level > 0 ? Math.floor(level) : 1;
	return template.replace('%level%', String(safeLevel)) as MorphId;
}

/**
 * Попробовать вытащить уровень из конкретного MorphId,
 * основываясь на шаблоне.
 *
 *   getLeveledMorphLevel("morph.rest.less-sleep.3", morph.rest.lessSleep)
 *   → 3
 *
 * Если id не подходит под шаблон — вернёт null.
 */
export function getLeveledMorphLevel(
	id: MorphId,
	template: LeveledMorphTemplateId,
): number | null {
	// из "morph.rest.less-sleep.%level%" делаем "morph.rest.less-sleep."
	const prefix = template.replace('%level%', '');
	if (!id.startsWith(prefix)) return null;

	const tail = id.slice(prefix.length); // "3" / "10" / "xyz"
	const num = Number.parseInt(tail, 10);
	if (!Number.isFinite(num) || num <= 0) return null;

	return num;
}
```

Теперь у тебя есть:

- генератор: `leveledMorph(morph.rest.lessSleep, 5)`;
- парсер: `getLeveledMorphLevel(id, morph.rest.lessSleep)`.

