		const currentRest = actor.getNeedValue(NeedTag.REST);
		if (currentRest > 0) {
			actor.changeNeedValue(NeedTag.REST, -currentRest);
		}
		return;
	}

	const sleepLengthMs = dailySleepHours * 60 * 60 * 1000;

	// 2. Гейты — тут больше НИКАКИХ тихих возвратов

	const enterGate = this.enterThresholds?.[NeedTag.REST];
	if (!enterGate) {
		throw new Error(
			`[Action SLEEP] Missing enterThresholds for REST. ` +
			`Ожидалось, что у экшена SLEEP будет enterThresholds[REST] с atLeast.`,
		);
