		throw new Error(
			`[Action SLEEP] enterThresholds[REST].atLeast не задан. ` +
			`SLEEP должен иметь минимальную зону входа (например IMPAIRED).`,
		);
	}

	const exitGate = this.exitThresholds?.[NeedTag.REST];
	if (!exitGate) {
		throw new Error(
			`[Action SLEEP] Missing exitThresholds for REST. ` +
			`Ожидалось, что у экшена SLEEP будет exitThresholds[REST] с atMost.`,
		);
	}
	if (!exitGate.atMost) {
		throw new Error(
			`[Action SLEEP] exitThresholds[REST].atMost не задан. ` +
			`SLEEP должен иметь зону выхода (например OK или WARN).`,
		);
	}

	const sleepZone =
		zoneRank(enterGate.atLeast) -
		zoneRank(exitGate.atMost);

	if (sleepZone <= 0) {
		throw new Error(
			`[Action SLEEP] Некорректная конфигурация зон: ` +
			`enterAtLeast(${enterGate.atLeast}) <= exitAtMost(${exitGate.atMost}). ` +
			`Для SLEEP логично иметь enter выше, чем exit.`,
		);
	}

	const reduceREST = (sleepZone / sleepLengthMs) * deltaTime;

	if (reduceREST > 0) {
