## 3. DRINK, переписанный с учётом water-морфов

Теперь обновим DRINK так, чтобы:

- он использовал `getDailyDrinkSeconds(actor)`;
- корректно обрабатывал случай `литров/сутки = 0` (существо не нуждается в воде);
- всё остальное — как у SLEEP: гейты, жёсткие проверки, зонная логика.

```ts
// rps/actions/living-creature.actions.ts (фрагмент с DRINK)

import { ActionDefinition } from "../action-definition";
import { ActionTag } from "../action-tags";
import { NeedTag, NeedThresholdEnum } from "../needs/needs";
import type { ActionContext } from "../types";
import { zoneRank } from "../needs/need-threshold-utils";
import { getDailyDrinkSeconds } from "../water/water-helpers";

export const DRINK: ActionDefinition = {
	tag: 'DRINK' as ActionTag,
	ctx: undefined as unknown as ActionContext,

	// Входим в DRINK, когда жажда ощутима.
	enterThresholds: {
		[NeedTag.WATER]: {
			atLeast: NeedThresholdEnum.WARN,
		},
	},

	// Выходим, когда жажда ушла в OK.
	exitThresholds: {
		[NeedTag.WATER]: {
			atMost: NeedThresholdEnum.OK,
		},
	},

	onEnter(ctx: ActionContext) {
		this.ctx = ctx;
		const actor = ctx.actor;

		if (actor.isBusy()) return;

		if (!actor.hasNeedTag(NeedTag.WATER)) {
			throw new Error(
				`[Action DRINK] Actor "${actor.id}" не имеет нужды WATER, ` +
				`но для него выбран экшен DRINK. Проверь профиль/линзы.`,
			);
		}

		// Считаем суточную потребность — в литрах → секунды
		const dailyDrinkSeconds = getDailyDrinkSeconds(actor);

		// Если существо в принципе НЕ нуждается в воде (литров/сутки = 0),
		// то логично:
		//  - сразу обнулить дефицит WATER (если он случайно есть);
		//  - не активировать состояние DRINK.
		if (dailyDrinkSeconds === 0) {
			const current = actor.getNeedValue(NeedTag.WATER);
			if (current > 0) {
				actor.changeNeedValue(NeedTag.WATER, -current);
			}
			return;
		}

		actor.setAction(this);
	},

	perform(deltaTime: number): void {
		const actor = this.ctx.actor;

		const dailyDrinkSeconds = getDailyDrinkSeconds(actor);
		if (dailyDrinkSeconds <= 0) {
			throw new Error(
				`[Action DRINK] dailyDrinkSeconds <= 0 в perform(), ` +
				`хотя onEnter должен был отфильтровать этот случай. ` +
				`Проверь морфы morph.water.* или логику onEnter.`,
			);
		}

		const drinkLengthMs = dailyDrinkSeconds * 1000;

		// ────────────────────────────────────────────────────
		// Проверки гейтов [WATER]
		// ────────────────────────────────────────────────────

		const enterGate = this.enterThresholds?.[NeedTag.WATER];
		if (!enterGate) {
			throw new Error(
				`[Action DRINK] Missing enterThresholds[WATER]. ` +
				`Нужно задать atLeast (например WARN/IMPAIRED).`,
			);
		}
		if (!enterGate.atLeast) {
			throw new Error(
				`[Action DRINK] enterThresholds[WATER].atLeast не задан. ` +
				`DRINK должен иметь минимальную зону входа (например WARN).`,
			);
		}

		const exitGate = this.exitThresholds?.[NeedTag.WATER];
		if (!exitGate) {
			throw new Error(
				`[Action DRINK] Missing exitThresholds[WATER]. ` +
				`Нужно задать atMost (например OK).`,
			);
		}
		if (!exitGate.atMost) {
			throw new Error(
				`[Action DRINK] exitThresholds[WATER].atMost не задан. ` +
				`DRINK должен иметь зону выхода (например OK).`,
			);
		}

		const drinkZone =
			zoneRank(enterGate.atLeast) -
			zoneRank(exitGate.atMost);

		if (drinkZone <= 0) {
			throw new Error(
				`[Action DRINK] Некорректные пороги: ` +
				`enterAtLeast(${enterGate.atLeast}) <= exitAtMost(${exitGate.atMost}). ` +
				`Для DRINK логично, чтобы зона входа была "хуже", чем зона выхода.`,
			);
		}

		// ────────────────────────────────────────────────────
		// Собственно утоление жажды
		// ────────────────────────────────────────────────────

		// drinkZone — "сколько зон" хотим пройти за суточную норму питья.
		const reduceWATER = (drinkZone / drinkLengthMs) * deltaTime;

		if (reduceWATER > 0) {
			actor.changeNeedValue(NeedTag.WATER, -reduceWATER);
		}

		// @TODO: когда появится модель ресурсов:
		//  - списывать литры воды из actor.inventory / hex.inventory;
		//  - если воды нет — либо прерывать DRINK, либо давать "сухой" эффект.
	},
};
```

---

### Итого

- Требуемое количество **воды** теперь задаётся морфами:

  ```ts
  morph.water.need.2      // базовая потребность 2 л/сутки
  morph.water.less-need.1 // -1 л
  morph.water.more-need.3 // +3 л
  ```

- `getDailyWaterNeedLiters(actor)` → считает итоговые литры в сутки по морфам.
- `getDailyDrinkSeconds(actor)` → превращает литры в секунды через скорость питья (литры/сек).
- DRINK работает по **той же архитектуре, что и SLEEP**:
  - гистерезис через enter/exitThresholds,
  - жёсткие проверки конфигурации,
  - ранний выход в `onEnter`, если существо вообще не нуждается в воде.

Дальше можно будет:

- подвязать `waterPerDay` из `MetabolismProfile` и синхронизировать его с morph.water.need;
- добавить морфы, меняющие скорость питья, а не только объём (широкий рот, маленькая пасть и т.п.).

