## 2. Хелперы для вместимости желудка

```ts
// rps/digest/digest-helpers.ts

import { morph } from "../morphs/morphs";
import { morphLvl } from "../morphs-leveled";
import type { ActorEntity } from "../world/actor.entity";

/**
 * Сколько фунтов содержимого желудок актёра может держать одновременно.
 *
 * Если морфа нет — дефолт 1 lb (человекоподобная норма).
 */
export function getStomachCapacityLb(actor: ActorEntity): number {
	const id = actor.findMorph(morph.digest.stomachCapacity);
	const lvl = morphLvl(id); // уровень = фунты

	const DEFAULT_CAPACITY_LB = 1;

	if (lvl <= 0) return DEFAULT_CAPACITY_LB;
	return lvl;
}
```

