## 3. Поле "заполненность желудка" в акторе

В акторе хранить текущую «забитость» желудка в фунтах:

```ts
// rps/world/actor.entity.ts (фрагмент)

import type { MorphId, LeveledMorphTemplateId } from "../morphs/morphs";
import { leveledMorphPrefix, getLeveledMorphLevel } from "../morphs-leveled";

// ...

export class ActorEntity {
	// ... остальные поля ...

	/**
	 * Текущая масса содержимого желудка (еда + вода), в фунтах.
	 *
	 * Это именно "то, что ещё не ушло дальше по пищеварению".
	 * Метаболизм/пищеварение со временем будет уменьшать это значение.
	 */
	protected stomachFillMassLb: number = 0;

	// --- морфы, как раньше ---
	getProfileMorphIds(): readonly MorphId[] {
		return (this.creatureProfile?.morphIds ?? []) as MorphId[];
	}

	hasMorph(id: MorphId): boolean {
		return this.getProfileMorphIds().includes(id);
	}

	findMorph(template: LeveledMorphTemplateId): MorphId | null {
		const ids = this.getProfileMorphIds();
		const prefix = leveledMorphPrefix(template);

		for (const id of ids) {
			if (id.startsWith(prefix)) return id as MorphId;
		}
		return null;
	}

	getMorphLevel(template: LeveledMorphTemplateId): number {
		const id = this.findMorph(template);
		if (!id) return 0;
		const lvl = getLeveledMorphLevel(id, template);
		return lvl ?? 0;
	}

	// --- желудок ---

	getStomachFillMassLb(): number {
		return this.stomachFillMassLb;
	}

	setStomachFillMassLb(massLb: number): this {
		this.stomachFillMassLb = Math.max(0, massLb);
		return this;
	}

	/**
	 * Изменить заполненность желудка (может быть отрицательной — "переваривание").
	 */
	changeStomachFillMassLb(deltaLb: number): this {
		return this.setStomachFillMassLb(this.stomachFillMassLb + deltaLb);
	}

	/**
	 * Сколько фунтов ещё влезет в желудок до полного.
	 */
	getStomachFreeCapacityLb(): number {
		const capacity = getStomachCapacityLb(this);
		return Math.max(0, capacity - this.stomachFillMassLb);
	}

	/**
	 * Закончить текущий экшен (вернуться в idle / дать планировщику выбрать следующее).
	 * Имя можешь поменять на то, которое у тебя уже заведено.
	 */
	finishCurrentAction(): this {
		this.currentAction = null as any; // или как у тебя хранится action
		return this;
	}
}
```

> Если у тебя уже есть другое имя для «сброса текущего экшена» — используй его. Суть в том, что DRINK/EAT должны иметь способ сказать: «я закончил, вытащи меня из состояния».

