## 2. Утилиты для уровневых морфов: позволяем SM быть отрицательным

Чуть чиним `morphs-leveled.ts`, чтобы уровни могли быть отрицательными (для SM это must-have):

```ts
// rps/morphs-leveled.ts

import type { LeveledMorphTemplateId, MorphId } from "./morphs";

/**
 * Сгенерировать конкретный MorphId из шаблона и уровня.
 *
 *   leveledMorph(morph.size.sm, -6) → "morph.size.sm.-6"
 *   leveledMorph(morph.rest.lessSleep, 3) → "morph.rest.less-sleep.3"
 */
export function leveledMorph(
	template: LeveledMorphTemplateId,
	level: number,
): MorphId {
	const safeLevel =
		Number.isFinite(level) ? Math.trunc(level) : 0;
	return template.replace('%level%', String(safeLevel)) as MorphId;
}

/** Префикс шаблона: "morph.size.sm.%level%" → "morph.size.sm." */
export function leveledMorphPrefix(template: LeveledMorphTemplateId): string {
	return template.replace('%level%', '');
}

/**
 * Извлечь уровень из MorphId, опционально проверяя шаблон.
 *
 * ВАЖНО: уровень может быть отрицательным или 0.
 */
export function getLeveledMorphLevel(
	id: MorphId,
	template?: LeveledMorphTemplateId,
): number | null {
	if (template && !id.startsWith(leveledMorphPrefix(template))) {
		return null;
	}

	const lastDot = id.lastIndexOf('.');
	if (lastDot === -1 || lastDot === id.length - 1) return null;

	const tail = id.slice(lastDot + 1); // "0", "-6", "2", ...
	const num = Number.parseInt(tail, 10);
	if (!Number.isFinite(num)) return null;

	return num;
}

/**
 * Общий хелпер "уровня" по MorphId.
 *
 * Для наших старых положительных морфов (lessSleep, water.need и т.п.)
 * смысл не меняется.
 *
 * Для SM:
 *   morphLvl("morph.size.sm.-6") → -6
 *   morphLvl("morph.size.sm.0")  → 0
 */
export function morphLvl(id: MorphId | null | undefined): number {
	if (!id) return 0;
	const lvl = getLeveledMorphLevel(id);
	return lvl ?? 0;
}
```

