### Вариант DRINK с явным инвариантом и без тихого цикла

```ts
import { ActionDefinition } from "../action-definition";
import { ActionTag } from "../action-tags";
import { NeedTag, NeedThresholdEnum } from "../needs/needs";
import type { ActionContext } from "../types";
import { zoneRank } from "../needs/need-threshold-utils";
import { getDailyWaterNeedLiters, getDailyDrinkSeconds } from "../water/water-helpers";

const WATER_LB_PER_LITER = 2; // округлённое игровое значение

export const DRINK: ActionDefinition = {
	tag: 'DRINK' as ActionTag,
	ctx: undefined as unknown as ActionContext,

	enterThresholds: {
		[NeedTag.WATER]: {
			atLeast: NeedThresholdEnum.WARN,
		},
	},

	// exitThresholds по WATER не задаём — выходим по желудку

	onEnter(ctx: ActionContext) {
		this.ctx = ctx;
		const actor = ctx.actor;

		if (actor.isBusy()) return;

		if (!actor.hasNeedTag(NeedTag.WATER)) {
			throw new Error(
				`[Action DRINK] Actor "${actor.id}" не имеет нужды WATER, ` +
				`но для него выбран экшен DRINK. Проверь профиль/линзы.`,
			);
		}

		const litersPerDay = getDailyWaterNeedLiters(actor);
		if (litersPerDay <= 0) {
			// "Doesn't Drink"-подобное состояние: с точки зрения логики
			// планировщик вообще НЕ должен был выбирать DRINK.
			// Но если выбрал — считаем, что это его баг и падаем громко.
			throw new Error(
				`[Action DRINK] litersPerDay <= 0 для актора "${actor.id}" ` +
				`(существо не нуждается в воде), но DRINK всё-таки выбран. ` +
				`Проверь логику планировщика.`,
			);
		}

		// ⬇️ ВОТ ТУТ главное изменение ⬇️
		const freeLb = actor.getStomachFreeCapacityLb();
		if (freeLb <= 0) {
			// Это НЕ "нормальный" путь выхода, а нарушение инварианта:
			// планировщик не должен выбирать DRINK при полном желудке.
			throw new Error(
				`[Action DRINK] onEnter вызван при полном желудке (freeLb=${freeLb}) ` +
				`для актора "${actor.id}". Проверяй планировщик: DRINK нельзя ` +
				`выбирать, когда getStomachFreeCapacityLb() <= 0.`,
			);
		}
		// ⬆️ вместо тихого return — жёсткий assert-инвариант ⬆️

		const dailyDrinkSeconds = getDailyDrinkSeconds(actor);
		if (dailyDrinkSeconds <= 0) {
			throw new Error(
				`[Action DRINK] getDailyDrinkSeconds() вернул ${dailyDrinkSeconds} ` +
				`для актора "${actor.id}". Проверь water-helpers и morph.water.*.`,
			);
		}

		actor.setAction(this);
	},

	perform(deltaTimeMs: number): void {
		const actor = this.ctx.actor;

		// 1) Нормальный выход по желудку во время выполнения
		const freeLbAtStart = actor.getStomachFreeCapacityLb();
		if (freeLbAtStart <= 0) {
			actor.finishCurrentAction();
			return;
		}

		// 2) Сколько воды нужно в сутки
		const litersPerDay = getDailyWaterNeedLiters(actor);
		if (litersPerDay <= 0) {
			throw new Error(
				`[Action DRINK] litersPerDay <= 0 в perform(), ` +
				`хотя onEnter должен был отфильтровать этот случай.`,
			);
		}

		const dailyDrinkSeconds = getDailyDrinkSeconds(actor);
		if (dailyDrinkSeconds <= 0) {
			throw new Error(
				`[Action DRINK] dailyDrinkSeconds <= 0 в perform().`,
			);
		}

		const drinkLengthMs = dailyDrinkSeconds * 1000;

		// 3) Зонная логика по WATER
		const enterGate = this.enterThresholds?.[NeedTag.WATER];
		if (!enterGate || !enterGate.atLeast) {
			throw new Error(
				`[Action DRINK] Некорректный enterThresholds[WATER]. ` +
				`Нужен хотя бы atLeast (например WARN).`,
			);
		}

		const targetExitZone = NeedThresholdEnum.OK;
		const drinkZone =
			zoneRank(enterGate.atLeast) -
			zoneRank(targetExitZone);

		if (drinkZone <= 0) {
			throw new Error(
				`[Action DRINK] Некорректный drinkZone (<=0). ` +
				`enterAtLeast=${enterGate.atLeast}, exitTarget=${targetExitZone}.`,
			);
		}

		// 4) "Идеальное" утоление жажды за этот тик (если бы желудок не ограничивал)
		const idealReduceWATER = (drinkZone / drinkLengthMs) * deltaTimeMs;
		if (idealReduceWATER <= 0) {
			return;
		}

		// 5) Идеальный объём воды за тик
		const deltaSec = deltaTimeMs / 1000;
		const drinkRateLps = litersPerDay / dailyDrinkSeconds; // литров в секунду
		const idealLitersThisTick = drinkRateLps * deltaSec;
		const idealMassThisTickLb = idealLitersThisTick * WATER_LB_PER_LITER;

		// 6) Ограничиваемся вместимостью желудка
		let actualMassThisTickLb = idealMassThisTickLb;
		let actualReduceWATER = idealReduceWATER;

		if (idealMassThisTickLb > freeLbAtStart) {
			const ratio = freeLbAtStart / idealMassThisTickLb;
			actualMassThisTickLb = freeLbAtStart;
			actualReduceWATER = idealReduceWATER * ratio;
		}

		actor.changeNeedValue(NeedTag.WATER, -actualReduceWATER);
		actor.changeStomachFillMassLb(actualMassThisTickLb);

		// Если забили желудок — выходим из экшена
		if (actualMassThisTickLb >= freeLbAtStart) {
			actor.finishCurrentAction();
		}
	},
};
```

### Что по-хорошему должен делать планировщик

Где-то снаружи (в планировщике) должно быть что-то логики типа:

```ts
function canEnterAction(actor: ActorEntity, action: ActionDefinition, ctx: ActionContext): boolean {
	// 1) Гейты по потребностям
	if (!needsPassEnterThresholds(actor, action.enterThresholds)) return false;

	// 2) Дополнительные физические/морфологические условия
	if (action.tag === 'DRINK' as ActionTag) {
		if (actor.getStomachFreeCapacityLb() <= 0) return false;
	}

	// (аналогично потом для EAT, SLEEP и т.п.)

	return true;
}
```

И тогда:

- при **полном желудке** DRINK вообще не попадает в список кандидатов → нет бесконечного цикла;
- если где-то всё же прорвётся и `onEnter` будет вызван с `freeLb <= 0` — мы словим это как **жёсткий баг** планировщика, а не «тихий нооп».

Если хочешь, дальше можем аналогично привести `EAT` к тому же паттерну: вход по FOOD-гейтам, выход по желудку, а планировщик смотрит и на нужды, и на `stomachFreeCapacity`.

Да, вот тут мы наконец пришли к нормальному решению: **планировщик отвечает за выбор**, экшен — за **жёсткие инварианты**, а не за «тихо уйти».  

Сделаем:

1. Кастомный класс ошибки «на вход экшена не пускаем, и НЕ пытайся сразу ещё раз».
2. В `DRINK.onEnter` просто кидаем эту ошибку, если желудок полон.

Трогать трешхолды и превращать желудок в отдельную «нужду» действительно не нужно — это костыль.

---

## 1. Кастомная ошибка для отказа во входе экшена

Создадим что-то вроде `ActionEnterRejectedError`. Пусть живёт, например, в `rps/actions/action-errors.ts`:

```ts
// rps/actions/action-errors.ts

import type { ActionTag } from "./action-tags";

/**
 * Специальная ошибка: "экшен НЕ МОЖЕТ быть начат в текущем состоянии".
 *
 * Важное семантическое отличие от обычного Error:
 *  - это НЕ баг кодовой логики,
 *  - это нормальный, ожидаемый отказ во входе,
 *  - планировщик должен:
 *      * не падать,
 *      * пометить этот экшен как "не брать сейчас",
 *      * перейти к выбору другого экшена.
 */
export class ActionEnterRejectedError extends Error {
	public readonly actionTag: ActionTag;
	public readonly reason: string;
	public readonly details?: unknown;

	constructor(actionTag: ActionTag, reason: string, details?: unknown) {
		super(`[ActionEnterRejected] ${String(actionTag)}: ${reason}`);
		this.name = "ActionEnterRejectedError";
		this.actionTag = actionTag;
		this.reason = reason;
		this.details = details;
	}
}
```

### Как планировщик должен это трактовать

Где-то в планировщике:

```ts
try {
	action.onEnter(ctx);
} catch (e) {
	if (e instanceof ActionEnterRejectedError) {
		// ✔ Нормальная ситуация:
		//   - НЕ логируем как баг,
		//   - НЕ перезапускаем этот экшен сразу,
		//   - идём подбирать другой.
		markActionAsRejectedForNow(e.actionTag, e.reason);
		return;
	}

	// Любая другая ошибка — реальный баг → пусть летит дальше
	throw e;
}
```

Как именно «помечать» экшен — уже твой дизайн (флаг, кэш на тик/на какое-то время и т.п.), но семантика очевидна: **этот экшен сейчас не подходит**, а не «сломался».

---

## 2. Правка `DRINK.onEnter` — только желудок

Теперь меняем только этот кусок в DRINK:

```ts
// rps/actions/living-creature.actions.ts (фрагмент)

import { ActionDefinition } from "../action-definition";
import { ActionTag } from "../action-tags";
import { NeedTag, NeedThresholdEnum } from "../needs/needs";
import type { ActionContext } from "../types";
import { getDailyWaterNeedLiters, getDailyDrinkSeconds } from "../water/water-helpers";
import { ActionEnterRejectedError } from "./action-errors"; // <-- новый импорт

export const DRINK: ActionDefinition = {
	tag: 'DRINK' as ActionTag,
	ctx: undefined as unknown as ActionContext,

	enterThresholds: {
		[NeedTag.WATER]: {
			atLeast: NeedThresholdEnum.WARN,
		},
	},

	// exitThresholds по WATER НЕ задаём — выход по желудку

	onEnter(ctx: ActionContext) {
		this.ctx = ctx;
		const actor = ctx.actor;

		if (actor.isBusy()) return;

		if (!actor.hasNeedTag(NeedTag.WATER)) {
			throw new Error(
				`[Action DRINK] Actor "${actor.id}" не имеет нужды WATER, ` +
				`но для него выбран экшен DRINK. Проверь профиль/линзы.`,
			);
		}

		const litersPerDay = getDailyWaterNeedLiters(actor);
		if (litersPerDay <= 0) {
			// Это уже логическая ошибка конфигурации профиля/морфов, а не "неподходящее состояние".
			throw new Error(
				`[Action DRINK] litersPerDay <= 0 для актора "${actor.id}" ` +
				`(существо не нуждается в воде), но DRINK вообще рассматривается. ` +
				`Проверь линзы/морфы morph.water.*.`,
			);
		}

		const freeLb = actor.getStomachFreeCapacityLb();

		if (freeLb <= 0) {
			// ВАЖНО: это НЕ баг, а "состояние не подходит":
			//   - желудок полон → пить сейчас нельзя/нет смысла;
			//   - планировщик не должен пытаться запускать DRINK ещё раз прямо сейчас.
			throw new ActionEnterRejectedError(
				this.tag,
				'STOMACH_FULL',
				{ actorId: actor.id, freeLb },
			);
		}

		const dailyDrinkSeconds = getDailyDrinkSeconds(actor);
		if (dailyDrinkSeconds <= 0) {
			throw new Error(
				`[Action DRINK] getDailyDrinkSeconds() вернул ${dailyDrinkSeconds} ` +
				`для актора "${actor.id}". Проверь water-helpers и morph.water.*.`,
			);
		}

		actor.setAction(this);
	},

	// perform(...) — без изменений, там как раз нормальный выход по желудку
};
```

Теперь:

- **DRINK сам по себе не уходит в тихий цикл** — при полном желудке он кидает *семантическую* ошибку `ActionEnterRejectedError`.
- Планировщик, увидев такую ошибку, понимает:  
  «Ок, DRINK сейчас невозможен (stomach full), пробую другой экшен»,  
  а не «надо перезапустить DRINK ещё раз».
- Трешхолды по нуждам остаются чистыми и не замусорены «желудочным» состоянием — как ты и хотел.

Если захочешь, можем следующим шагом:

- добавить ещё парочку reason-кодов (`NO_WATER_SOURCE`, `HANDS_BUSY`, ...);
- и договориться о формате `details`, чтобы планировщик мог логировать причину отказа без кривых `instanceof` и парсинга сообщений.

Да, ты абсолютно прав: сейчас DRINK магически «утоляет жажду» из воздуха. Надо, чтобы он реально **брал воду из мира** — из инвентаря и/или гекса — и уже на основе того, *сколько воды реально найдено и выпито*,:

- заполнял желудок;
- уменьшал дефицит WATER;
- и, если воды нет — корректно завершался (и сообщал планировщику `NO_WATER_SOURCE`, если надо).

Я покажу два куска:

1. Хелпер `drinkFromWorld(...)`, который *ищет и списывает воду* из инвентаря и гекса.
2. Обновлённый `DRINK.perform`, который пользуется этим хелпером.

Имён методов инвентаря/гекса у тебя может ещё не быть — я специально помечу места `@TODO`, чтобы было понятно, куда подвесить реальные вызовы.

